from __future__ import annotations

import heapq
from dataclasses import dataclass
from typing import Callable, Mapping

from .errors import SchedulerError


@dataclass(frozen=True)
class ScheduledInvocation:
    tick: int
    phase: int
    sequence: int
    task_id: str


@dataclass(frozen=True)
class PeriodicTask:
    task_id: str
    period_ticks: int
    phase: int


class DeterministicScheduler:
    """Integer-tick scheduler with stable phase and registration ordering."""

    def __init__(self, *, start_tick: int = 0):
        if start_tick < 0:
            raise SchedulerError("Scheduler start tick cannot be negative.")
        self.current_tick = start_tick
        self._queue: list[tuple[int, int, int, str]] = []
        self._tasks: dict[str, PeriodicTask] = {}
        self._registration_sequence = 0
        self._invocation_sequence = 0

    def register_periodic(
        self,
        task_id: str,
        *,
        period_ticks: int,
        phase: int,
        first_tick: int | None = None,
    ) -> None:
        if task_id in self._tasks:
