/// CHE calculation components per NEAL-CORE spec
/// Formula: raw = (1 - Var)(1 - DDI)(1 - κ), then softmax normalize
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CheComponents {
    /// Weighted stance mean (DiSC formula)
    /// μ = Σⱼ(wⱼ·sⱼ) / Σⱼ(wⱼ) where wⱼ = r_dⱼ · e_dⱼ · τ_dⱼ
    pub stance_mean: f64,
    /// Weighted variance across domains
    /// Var = Σⱼ wⱼ(sⱼ - μ)² / Σⱼ wⱼ
    pub variance: f64,
    /// Domain Disagreement Index (high-weight domains only, w > 0.5)
    /// DDI = Σⱼ∈H(wⱼ(sⱼ - μ)²) / Σⱼ∈H wⱼ
    pub ddi: f64,
    /// Starmap curvature penalty κ ∈ [0,1]
    pub curvature_kappa: f64,
    /// Raw energy: (1 - Var)(1 - DDI)(1 - κ)
    pub raw_energy: f64,
    /// Normalized CHE score via softmax
    pub che_score: f64,
    /// SECR: Stance-to-Evidence Consistency Ratio (cosine alignment)
    pub secr: f64,
}

impl CheComponents {
    pub fn new() -> Self {
        Self {
            stance_mean: 0.0,
            variance: 0.0,
            ddi: 0.0,
            curvature_kappa: 0.0,
            raw_energy: 0.0,
            che_score: 0.0,
            secr: 0.0,
        }
    }
}

impl Default for CheComponents {
    fn default() -> Self {
        Self::new()
    }
}

/// Domain stance evidence tuple for CHE calculation
pub struct DomainStance {
    pub domain: String,
    pub stance: f64,        // s_d ∈ [-1, 1]
    pub evidence: f64,      // e_d ∈ [0, 1]
    pub relevance: f64,     // r_d ∈ [0, 1]
    pub temporal: f64,      // τ_d ∈ [0, 1] (recency weight)
}

/// Calculate CHE for a set of domain stances
pub(crate) fn calculate_che(stances: &[DomainStance], curvature: f64) -> CheComponents {
    if stances.is_empty() {
        return CheComponents::new();
    }

    // Calculate weights: w_d = r_d × e_d × τ_d
    let weighted: Vec<(f64, f64)> = stances.iter()
        .map(|s| {
            let weight = s.relevance * s.evidence * s.temporal;
            (weight, s.stance)
        })
        .collect();

    let total_weight: f64 = weighted.iter().map(|(w, _)| w).sum();

    if total_weight < 1e-10 {
        return CheComponents {
            variance: 1.0,
            ddi: 1.0,
            raw_energy: 0.0,
            ..Default::default()
        };
