fn downsample_embeddings(
    embeddings: &[Vec<f32>],
    target_count: usize,
) -> Vec<Vec<f32>> {
    use rand::seq::SliceRandom;

    let mut rng = rand::thread_rng();
    let mut indices: Vec<usize> = (0..embeddings.len()).collect();
    indices.shuffle(&mut rng);

    indices
        .into_iter()
        .take(target_count)
