    /// Add sample with reservoir sampling
    pub fn add(&mut self, sample: ConsolidationSample) {
        self.total_seen = self.total_seen.saturating_add(1);

        if self.samples.len() < self.capacity {
            self.samples.push(sample);
        } else {
            // Reservoir sampling: replace with probability capacity/total_seen
            let idx = self.rng.gen_range(0..self.total_seen as usize);
            if idx < self.capacity {
                self.samples[idx] = sample;
            }
        }
    }

